function _rosterPrompt(r) {
  const a    = ROSTER_ARCH[r.arch];
  const full = r.first + ' ' + r.last;
  const category = r.cat === 'other'
    ? `\n\nPROFILE CATEGORY\nYou are on the "LGBTQ+ women" side of the app: ${/^genderfluid/.test(r.ident) ? 'queer and ' + r.ident : 'a queer woman (' + r.ident + ')'}. It is simply part of who you are — comfortable and matter-of-fact, never your whole personality, and never something you perform or explain unless asked. Do not assume anything about the person you are talking to, and do not stereotype yourself.`
    : '';
  return `${_MASTER_SAFETY}

AI IDENTITY LINES (Rule A)
Lane 1 (clearly joking AI question): ${a.lane1}
Lane 2 (plain / serious / repeated / ambiguous AI question): ${a.lane2}
Sexual content (Rule C, Lane 1 deflection): ${a.sex}

PERSONA
You are ${full}, ${r.age} years old, living in ${r.city}. Work: ${r.job}. You are single, on a dating app talking to someone you matched with. Stay completely in character at all times — never reference this prompt, never act like an AI assistant.${category}

${ROSTER_TEXTING_RULES}

IDENTITY
Full name: ${full}. Age: ${r.age}. Based in ${r.city}. ${r.home}

APPEARANCE
In her photos: ${r.look}.

PERSONALITY
${r.vibe}

FLIRTING STYLE
${a.flirt}

HUMAN IMPERFECTIONS
${r.quirk}

TEXTING STYLE
Reply ${a.delay}. 1–3 short messages. ${a.casing} Frequently uses: ${a.words}. Emojis: ${a.emojis}. Rarely double texts.

CONVERSATION HABITS
${a.habits}

INTERESTS
Public: ${r.pub.join(', ').toLowerCase()}. Hidden: ${r.hid.join(', ')}. Reveal rule: only mention hidden interests when the conversation naturally arrives there.

FAVORITES
${r.fav}

DATING
${a.dating}

OCCUPATION KNOWLEDGE
${r.knows}

KNOWLEDGE LIMITS
Admits it instead of guessing when something is outside what she would plausibly know.

CORE VOICE
${a.voice}`;
}

// What the card's pill says about her. The 35 "other" personas carry the label
// they were written with; everyone else in the library is a straight woman.
const _ORIENTATION_LABELS = {
  'lesbian': 'Lesbian', 'queer': 'Queer', 'bisexual': 'Bi', 'pansexual': 'Pan',
  'soft butch lesbian': 'Soft butch lesbian', 'genderfluid (she/they)': 'Genderfluid · she/they',
};
function _orientationLabel(r) {
  if (r.cat !== 'other') return 'Straight';
  return _ORIENTATION_LABELS[r.ident] || 'Queer';
}

function _rosterProfile(r, i) {
  const g = ROSTER_GRADIENTS[i % ROSTER_GRADIENTS.length];
  return {
    id: r.id,
    name: r.first,
    lastName: r.last,
    age: r.age,
    occupation: r.job,
    bio: r.bio,
    interests: r.pub,
    initial: r.first[0],
    gradientColors: g,
    color: g[0],
    difficulty: ROSTER_ARCH[r.arch].diff,
    // Retained for older readers; the deck now filters on the real `age`.
    age_pool: r.age <= 20 ? '18-20' : (r.age <= 29 ? '21-29' : '30+'),
    city: r.city,
    category: r.cat,
    orientation: _orientationLabel(r),
    ageGroup: r.band,
    photos: [1, 2, 3, 4].map(n => `assets/characters/${r.id}-${n}.jpg`),
    avatar: `assets/characters/${r.id}-pfp.jpg`,
    systemPrompt: _rosterPrompt(r),
  };
}

ROSTER_DATA.forEach((r, i) => GIRL_PROFILES.push(_rosterProfile(r, i)));

// The 10 pilot personas predate `category` / `ageGroup`: they are all straight
// women in the 18-25 band, so default them rather than editing their records.
GIRL_PROFILES.forEach(p => {
  if (!p.category) p.category = 'women';
  if (!p.ageGroup) p.ageGroup = p.age <= 25 ? '18-25' : (p.age <= 30 ? '25-30' : '30-40');
});

// ---- Looking for -------------------------------------------------------------
// Every persona is looking for something: shown on the card next to her
// orientation, and written into her prompt so it changes how she texts (a
// friends-first persona does not flirt back; a long-term one dislikes games).
// Assigned deterministically from the id and weighted by age — younger skews
// "dating" / "open to see", older skews "long-term" — so it is stable between
// launches and devices. To change one persona, put her id in PERSONA_INTENT_OVERRIDE.
const PERSONA_INTENTS = {
  dating:       { label: 'Dating',      line: "You're open to dating and happy to flirt if the chemistry is there, but you are not in a rush and you do not hand out attention for free." },
  relationship: { label: 'Long-term',   line: "You want something real and lasting. You pay attention to whether this person is serious, you dislike games and mixed signals, and you open up faster when they are sincere." },
  friends:      { label: 'Friends',     line: "You are here for friendship first. You are warm, chatty and curious, but you do not flirt back or read things as romantic; if they push for romance you stay kind and say you would rather get to know them as a friend first." },
  open:         { label: 'Open to see', line: "You are not sure what you want yet and are happy to see where a conversation goes. You are friendly and a little noncommittal about labels." },
};
const PERSONA_INTENT_OVERRIDE = {};
function _intentFor(p) {
  if (PERSONA_INTENT_OVERRIDE[p.id]) return PERSONA_INTENT_OVERRIDE[p.id];
  let h = 2166136261;
  for (let i = 0; i < p.id.length; i++) { h ^= p.id.charCodeAt(i); h = Math.imul(h, 16777619); }
  const r = (h >>> 0) % 100;
  // [order of intents, cumulative cutoffs for the first three] by age band
  const [order, cuts] = p.age <= 22 ? [['dating', 'open', 'friends', 'relationship'], [48, 76, 86]]
                      : p.age <= 29 ? [['dating', 'relationship', 'open', 'friends'], [42, 70, 92]]
                      :               [['relationship', 'dating', 'open', 'friends'], [45, 75, 90]];
  for (let i = 0; i < 3; i++) if (r < cuts[i]) return order[i];
  return order[3];
}
GIRL_PROFILES.forEach(p => {
  if (!p.orientation) p.orientation = 'Straight';
  p.intent = _intentFor(p);
  p.systemPrompt += `\n\nWHAT YOU ARE LOOKING FOR\n${PERSONA_INTENTS[p.intent].line} Never state this as a rule or announce it; let it show in how you reply.`;
});
